import { MeshBasicNodeMaterial } from 'three/webgpu';
import {
  uv,
  vec2,
  vec3,
  vec4,
  mix,
  uniform,
  texture,
  fract,
  sin,
  dot,
  clamp,
} from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const { Group, PlaneGeometry, Color, DoubleSide } = THREE;

  const colors = (config.intent?.visualSpec?.colors) ?? config.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  const group = new Group();
  group.name = 'features-card-2-floating-accent';

  // --- atlas region -> aspect ratio -------------------------------------
  const rect = { x: 0, y: 0, w: 512, h: 320 };
  const aspect = rect.w / rect.h;
  const baseWidth = 1.35; // scene units — subtle accent, not the hero
  const baseHeight = baseWidth / aspect;

  // ---------------------------------------------------------------------
  // Backdrop: engineered gradient surface behind the accent sprite so it
  // never reads as a lone unlit cutout floating in void.
  // ---------------------------------------------------------------------
  const backdropGeo = new PlaneGeometry(baseWidth * 1.28, baseHeight * 1.35, 1, 1);
  const backdropMat = new MeshBasicNodeMaterial({ transparent: true, side: DoubleSide });

  const colorSurface = vec3(new Color(colors.surface).r, new Color(colors.surface).g, new Color(colors.surface).b);
  const colorInk = vec3(new Color(colors.ink).r, new Color(colors.ink).g, new Color(colors.ink).b);

  const vUv = uv();
  // vertical engineered gradient, no soft pastel blur — hard-edged mix curve
  const gradT = clamp(vUv.y.mul(0.85).add(0.1), 0.0, 1.0);
  backdropMat.colorNode = mix(colorSurface, colorInk, gradT);
  backdropMat.opacityNode = uniform(0.9);

  const backdrop = new THREE.Mesh(backdropGeo, backdropMat);
  backdrop.position.z = -0.02;
  group.add(backdrop);

  // ---------------------------------------------------------------------
  // Foreground sprite: the actual floating-accent image, billboarded flat
  // toward the camera (camera looks down -z, plane already faces +z).
  // ---------------------------------------------------------------------
  const spriteGeo = new PlaneGeometry(baseWidth, baseHeight, 1, 1);
  const spriteMat = new MeshBasicNodeMaterial({ transparent: true, side: DoubleSide, depthWrite: false });

  const uOpacity = uniform(0);
  const uGrain = uniform(0.035); // subtle grain amount

  // cheap deterministic pseudo-random grain (static, no time dependence —
  // keeps this a static composition per spec)
  const suv = uv();
  const grainSeed = fract(sin(dot(suv, vec2(12.9898, 78.233))).mul(43758.5453));
  const grainSigned = grainSeed.sub(0.5).mul(uGrain);

  spriteMat.map = null; // set once texture resolves
  spriteMat.colorNode = vec4(vec3(grainSigned), 0.0).add(
    vec4(1.0, 1.0, 1.0, 1.0)
  ).mul(vec4(1, 1, 1, 1)); // placeholder, replaced below once map exists

  const sprite = new THREE.Mesh(spriteGeo, spriteMat);
  sprite.position.z = 0.0;
  group.add(sprite);

  let disposedTexture = null;

  const imageUrl = config.imageUrl ?? config.intent?.visualSpec?.imageUrl ?? null;
  if (imageUrl) {
    ctx.textureLoader.loadTexture(imageUrl).then((tex) => {
      disposedTexture = tex;
      spriteMat.map = tex;
      const texNode = texture(tex, suv);
      // composite subtle grain onto the sampled texture, preserve alpha
      spriteMat.colorNode = vec4(texNode.rgb.add(vec3(grainSigned)), 1.0);
      spriteMat.opacityNode = texNode.a.mul(uOpacity);
      spriteMat.needsUpdate = true;
    }).catch(() => {
      // fail quiet — keep backdrop gradient visible so node never renders void
    });
  } else {
    spriteMat.opacityNode = uOpacity;
  }

  // ---------------------------------------------------------------------
  // Motion: weighted-settle entrance (no idle perpetual motion — this is a
  // static composition per the spec's effects vocabulary).
  // ---------------------------------------------------------------------
  group.position.y += 0; // adapter applies scenePosition; local offset stays 0
  sprite.scale.set(0.98, 0.98, 1);
  backdrop.scale.set(0.98, 0.98, 1);

  const tl = gsap.timeline({ delay: 0.05 });
  tl.to(uOpacity, { value: 1, duration: 0.6, ease: 'power2.out' });
  tl.to(sprite.scale, { x: 1.04, y: 1.04, duration: 0.35, ease: 'power3.out' }, 0);
  tl.to(sprite.scale, { x: 1.0, y: 1.0, duration: 0.55, ease: 'power4.out' }, 0.35);
  tl.to(backdrop.scale, { x: 1.0, y: 1.0, duration: 0.9, ease: 'power4.out' }, 0);
  tl.to(sprite.position, { y: '+=0', duration: 0.01 }, 0); // no-op keeps translate <=0.4 discipline explicit

  group.userData.handlers = {};

  group.userData.cleanup = () => {
    tl.kill();
    gsap.killTweensOf(uOpacity);
    gsap.killTweensOf(sprite.scale);
    gsap.killTweensOf(backdrop.scale);

    spriteGeo.dispose();
    backdropGeo.dispose();
    spriteMat.dispose();
    backdropMat.dispose();

    if (disposedTexture && typeof disposedTexture.dispose === 'function') {
      disposedTexture.dispose();
    }
  };

  return group;
}
